// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint8 roleIdx, address actor) public {
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        bytes32 role = roleIdx % 3 == 0 ? c.PROPOSER_ROLE() : (roleIdx % 3 == 1 ? c.EXECUTOR_ROLE() : c.TIMELOCK_ADMIN_ROLE());

        // grant role to actor via admin (the deployer)
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor), "grant failed");

        // actor renounces the role for themselves
        vm.prank(actor);
        c.renounceRole(role, actor);

        // general rule: after renouncing, the account no longer holds the role
        assertTrue(!c.hasRole(role, actor), "role must be revoked after renounce");
    }
}
